  const statementRows = (p: (typeof people)[number]) =>
    claims
      .filter((c) => c.personId === p.id && c.stated)
      .reverse()
      .map((c) => [
        c.number,
        c.date,
        c.amount,
        showDue(claimDue(c, claimRate(rates, gradeOn(p, c.date), c), floor, { pct: latePct, today, grace }, policy)),
        c.status,
      ]);
  const claimRows = () =>
    people.flatMap((p) =>
      claims
        .filter((c) => c.personId === p.id)
        .reverse()
        .map((c) => [
          p.name,
          c.number,
          c.date,
          c.amount,
          showDue(claimDue(c, claimRate(rates, gradeOn(p, c.date), c), floor, { pct: latePct, today, grace }, policy)),
          c.status,
          periodOf(periods, dueBy(c))?.name ?? '',
        ]),
    );

